for (const id of ["network", "codes", "errors", "osi"]) teachingUnits[id].support = "/estudio/fuentes/F35.pdf";
function lessonTeaching(lesson, step) {
  if (lesson.id === "ri-teoria") return teachingUnits[{ red: "network", codigos: "codes", errores: "errors", osi: "osi" }[step.id] || "network"];
  if (lesson.id === "ri-cable") return teachingUnits.cable;
  if (lesson.id === "ii-metrologia") return teachingUnits[step.id.endsWith("media") ? "sampleMean" : step.id.includes("dispersion") ? "sampleDeviation" : "metrology"];
  if (lesson.id === "ii-fundamentos") return teachingUnits[["equipos", "funciones", "variables", "tarea"].includes(step.id) ? "classification" : "automation"];
  const lessonKeys = { "ii-caudal": "flow", "ii-presion": "pressure", "ii-nivel": "level", "ii-temperatura-teoria": "temperature", "ii-proximidad-teoria": "proximity", "ea-clase-1": "signal", "ea-clase-2": "diode", "ea-clase-3": "transistor", "ea-clase-4": "bridge", "ea-clase-5": "opamp", "ea-ajuste-cero": "calibration", "ea-guia-ao": step.id === "ej3" || step.id === "ej4" ? "calibration" : "opamp", "cm-cc": "dcMotor", "cm-ca": "acMotor", "cm-arranque-manual": "starDelta", "mt-piedra": "quadratic", "mt-piedra-extension": "quadratic", "mt-servicio": "affine", "mt-energia": "affine", "mt-energia-extension": "affine", "mt-instagram": "logarithm", "mt-sueno": "business", "mt-stock": "stock" };
  return teachingUnits[lessonKeys[lesson.id] || "classification"];
}
